CREATE OR REPLACE FUNCTION public.dawaa_can_access_customer_request_branch(p_permission text, p_branch text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_actor_id uuid;
  v_role text;
  v_branch text;
begin
  v_actor_id := public.dawaa_current_staff_account_id_strict();
  if v_actor_id is null then return false; end if;
  if not public.dawaa_customer_request_permission_allowed(v_actor_id, p_permission) then return false; end if;

  select lower(trim(coalesce(sa.role,''))), sa.branch
    into v_role, v_branch
  from public.staff_accounts sa
  where sa.id = v_actor_id
    and coalesce(sa.active,false)
    and coalesce(sa.can_login,false)
  limit 1;

  if not found then return false; end if;
  if v_role in ('general_manager','executive_manager','branches_manager','admin') then return true; end if;

  return public.dawaa_customer_request_branch_key(v_branch) is not null
    and public.dawaa_customer_request_branch_key(v_branch) = public.dawaa_customer_request_branch_key(p_branch);
end;
$function$

CREATE OR REPLACE FUNCTION public.dawaa_current_actor_can(required_permissions text[])
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_staff_id uuid;
  v_role text;
  v_permissions jsonb;
  v_profile_role text;
  v_profile_active boolean;
  v_profile_permissions jsonb;
begin
  v_staff_id := public.dawaa_current_staff_account_id_strict();

  if v_staff_id is not null then
    select sa.role, public.get_user_permissions(sa.id)
      into v_role, v_permissions
    from public.staff_accounts sa
    where sa.id = v_staff_id
      and coalesce(sa.active,false)
      and coalesce(sa.can_login,false)
    limit 1;

    if found then
      if lower(trim(coalesce(v_role,''))) in ('general_manager','admin') then return true; end if;
      return public.dawaa_jsonb_has_true_any(coalesce(v_permissions,'{}'::jsonb), required_permissions);
    end if;
  end if;

  select lower(trim(coalesce(up.role,''))), coalesce(up.active,true), coalesce(up.permissions,'{}'::jsonb)
    into v_profile_role, v_profile_active, v_profile_permissions
  from public.user_profiles up
  where auth.uid() is not null
    and up.auth_user_id = auth.uid()
    and up.staff_account_id is null
  limit 1;

  if not found or not v_profile_active then return false; end if;
  if v_profile_role in ('مدير عام','أدمن','admin','general_manager','مدير') then return true; end if;
  return public.dawaa_jsonb_has_true_any(v_profile_permissions, required_permissions);
end;
$function$

CREATE OR REPLACE FUNCTION public.dawaa_materialize_whatsapp_action_core_v2(p_action_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_action public.whatsapp_conversation_actions%rowtype;
  v_source public.whatsapp_review_sources%rowtype;
  v_result jsonb;
  v_target_id text;
  v_priority text;
  v_request_type text;
  v_needed_date date;
begin
  if public.dawaa_current_staff_account_id_strict() is null then
    raise exception 'not_authorized';
  end if;

  select * into v_action
  from public.whatsapp_conversation_actions
  where id = p_action_id
  for update;

  if v_action.id is null then raise exception 'whatsapp_action_not_found'; end if;

  select * into v_source from public.whatsapp_review_sources where id = v_action.source_id;
  if v_source.id is null then raise exception 'whatsapp_source_not_found'; end if;

  if not public.dawaa_can_read_conversation_review_row_v2(
    public.dawaa_current_staff_account_id_strict(), v_source.staff_id, null::uuid, v_source.branch, null::uuid
  ) then raise exception 'whatsapp_action_access_denied'; end if;

  if v_action.status = 'created' then
    return jsonb_build_object('ok',true,'already_created',true,'action_id',v_action.id,'target_table',v_action.target_table,'target_id',v_action.target_id);
  end if;
  if v_action.status not in ('ready','proposed') then raise exception 'whatsapp_action_not_materializable'; end if;

  if v_action.action_type = 'customer_request' then
    -- Explicit execution is required because customer request registration can trigger incentive credit.
    if v_action.status <> 'ready' or not v_action.auto_eligible then raise exception 'customer_request_requires_ready_verified_action'; end if;
    if v_action.customer_id is null then raise exception 'customer_request_customer_required'; end if;
    if v_action.product_id is null then raise exception 'customer_request_product_required'; end if;
    if v_action.staff_id is null then raise exception 'customer_request_doctor_required'; end if;
    v_priority := case when coalesce(v_action.payload->>'urgency','normal')='urgent' then 'urgent' else 'normal' end;
    v_request_type := coalesce(nullif(v_action.payload->>'request_type',''),'missing_medicine');
    v_needed_date := case when v_action.due_at is null then null else (v_action.due_at at time zone 'Africa/Cairo')::date end;
    v_result := public.create_customer_request_canonical_v2(
      v_action.customer_id, v_action.product_id, v_action.staff_id, v_action.branch,
      coalesce(v_action.quantity,1), v_priority, v_request_type, 'whatsapp', v_needed_date,
      null, null, concat_ws(E'\n',v_action.reason,'WhatsApp source: '||v_action.source_id::text), null, null
    );
    v_target_id := nullif(v_result->'request'->>'id','');
    if v_target_id is null then raise exception 'customer_request_creation_did_not_return_id'; end if;
    update public.whatsapp_conversation_actions set status='created',target_table='customer_requests',target_id=v_target_id,last_error=null,updated_at=now() where id=v_action.id;

  elsif v_action.action_type in ('customer_followup','recommendation_followup','complaint_followup') then
    if nullif(trim(coalesce(v_action.customer_name,'')),'') is null then raise exception 'followup_customer_name_required'; end if;
    if nullif(trim(coalesce(v_action.branch,'')),'') is null then raise exception 'followup_branch_required'; end if;
    v_request_type := case v_action.action_type when 'recommendation_followup' then 'recommendation' when 'complaint_followup' then 'complaint' else 'general' end;
    v_priority := case when v_action.action_type='complaint_followup' then 'عالية' when coalesce(v_action.payload->>'priority','')='urgent' then 'عالية' when coalesce(v_action.payload->>'priority','')='important' then 'متوسطة' else 'متوسطة' end;
    v_needed_date := case when v_action.due_at is null then null else (v_action.due_at at time zone 'Africa/Cairo')::date end;
    v_result := public.dawaa_create_or_link_customer_followup_v1(
      v_action.customer_id::text, v_action.customer_code, v_action.customer_name, v_action.customer_phone,
      v_action.branch, v_request_type,
      concat_ws(E'\n',v_action.reason,case when v_action.product_name is not null then 'الصنف: '||v_action.product_name else null end),
      v_action.reason, v_priority, v_needed_date,
      'whatsapp-action:'||v_action.id::text, 'whatsapp_review_v6'
    );
    v_target_id := nullif(v_result->>'followup_id','');
    if v_target_id is null then raise exception 'followup_creation_did_not_return_id'; end if;
    update public.whatsapp_conversation_actions set status='created',target_table='daily_followups',target_id=v_target_id,last_error=null,updated_at=now() where id=v_action.id;

  else
    raise exception 'action_type_requires_manual_handling';
  end if;

  insert into public.whatsapp_review_audit(source_id,action,actor_id,actor_name,actor_role,before_state,after_state,note)
  select v_action.source_id,'operational_action_materialized',a.id::text,coalesce(a.name,a.username),coalesce(a.role,a.staff_role),to_jsonb(v_action),
         jsonb_build_object('action_id',v_action.id,'target_table',case when v_action.action_type='customer_request' then 'customer_requests' else 'daily_followups' end,'target_id',v_target_id,'result',v_result),
         'تم تنفيذ إجراء تشغيلي من WhatsApp Review بعد إجراء المستخدم الصريح.'
  from public.staff_accounts a where a.id=public.dawaa_current_staff_account_id_strict() limit 1;

  return jsonb_build_object('ok',true,'already_created',false,'action_id',v_action.id,'target_id',v_target_id,'result',v_result);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_user_permissions(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_staff_account_id uuid;
  v_role text;
  v_allowed_pages text[];
  v_account_permissions jsonb := '{}'::jsonb;
  v_role_json jsonb := '{}'::jsonb;
  v_pages_json jsonb := '{}'::jsonb;
  v_override_json jsonb := '{}'::jsonb;
  v_effective jsonb := '{}'::jsonb;
  v_role_key text;
  v_can_view_reviews boolean := false;
  v_can_add_reviews boolean := false;
  v_can_edit_reviews boolean := false;
  v_can_approve_reviews boolean := false;
  v_can_delete_reviews boolean := false;
  v_can_view_shift_performance boolean := false;
  v_can_create_shift_evaluation boolean := false;
  v_can_edit_shift_evaluation boolean := false;
  v_can_approve_shift_evaluation boolean := false;
  v_can_delete_shift_evaluation boolean := false;
  v_can_view_points boolean := false;
  v_can_manage_points boolean := false;
  v_can_approve_points boolean := false;
  v_can_create_reward boolean := false;
  v_can_create_deduction boolean := false;
  v_can_edit_points_transaction boolean := false;
  v_can_export_points_report boolean := false;
  v_can_view_salary_calculator boolean := false;
  v_can_manage_payroll boolean := false;
  v_can_view_incentives boolean := false;
  v_can_manage_incentives boolean := false;
  v_can_view_quarterly_incentives boolean := false;
  v_can_manage_quarterly_incentives boolean := false;
  v_can_view_penalty_management boolean := false;
  v_can_manage_penalty_management boolean := false;
begin
  select id, role, allowed_pages, coalesce(permissions, '{}'::jsonb)
  into v_staff_account_id, v_role, v_allowed_pages, v_account_permissions
  from public.staff_accounts
  where (id = p_user_id or auth_user_id = p_user_id)
    and coalesce(active, false)
    and coalesce(can_login, false)
  order by case when id = p_user_id then 0 else 1 end, updated_at desc nulls last
  limit 1;
  if v_staff_account_id is null then return '{}'::jsonb; end if;

  select coalesce(jsonb_object_agg(permission_key, allowed), '{}'::jsonb) into v_role_json
  from public.app_role_section_permissions where role_key = v_role;
  select coalesce(jsonb_object_agg(x, true), '{}'::jsonb) into v_pages_json
  from unnest(coalesce(v_allowed_pages, '{}'::text[])) as x;
  select coalesce(jsonb_object_agg(permission_key, allowed), '{}'::jsonb) into v_override_json
  from public.staff_permission_overrides where staff_account_id = v_staff_account_id;
  v_effective := v_role_json || v_pages_json || v_account_permissions || v_override_json;
  v_role_key := lower(trim(coalesce(v_role, '')));

  if v_role_key in ('general_manager','executive_manager','branches_manager','admin') then
    v_can_view_reviews := true; v_can_add_reviews := true; v_can_edit_reviews := true; v_can_approve_reviews := true; v_can_delete_reviews := true;
  elsif v_role_key in ('branch_manager','customer_service_manager') then
    v_can_view_reviews := true; v_can_add_reviews := true; v_can_edit_reviews := true; v_can_approve_reviews := true;
  elsif v_role_key in ('shift_supervisor_morning','shift_supervisor_evening','customer_service','team_dawaa_alpha') then
    v_can_view_reviews := true; v_can_add_reviews := true;
  elsif v_role_key in ('pharmacist','assistant') then v_can_view_reviews := true;
  end if;
  v_effective := jsonb_set(v_effective, '{view_reviews}', to_jsonb(v_can_view_reviews and coalesce(nullif(v_account_permissions->>'view_reviews','')::boolean, true) and coalesce(nullif(v_override_json->>'view_reviews','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{add_reviews}', to_jsonb(v_can_add_reviews and coalesce(nullif(v_account_permissions->>'add_reviews','')::boolean, true) and coalesce(nullif(v_override_json->>'add_reviews','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{edit_reviews}', to_jsonb(v_can_edit_reviews and coalesce(nullif(v_account_permissions->>'edit_reviews','')::boolean, true) and coalesce(nullif(v_override_json->>'edit_reviews','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{approve_reviews}', to_jsonb(v_can_approve_reviews and coalesce(nullif(v_account_permissions->>'approve_reviews','')::boolean, true) and coalesce(nullif(v_override_json->>'approve_reviews','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{delete_reviews}', to_jsonb(v_can_delete_reviews and coalesce(nullif(v_account_permissions->>'delete_reviews','')::boolean, true) and coalesce(nullif(v_override_json->>'delete_reviews','')::boolean, true)), true);

  if v_role_key in ('general_manager','executive_manager','branches_manager','admin') then
    v_can_view_shift_performance := true; v_can_create_shift_evaluation := true; v_can_edit_shift_evaluation := true; v_can_approve_shift_evaluation := true; v_can_delete_shift_evaluation := true;
  elsif v_role_key = 'branch_manager' then
    v_can_view_shift_performance := true; v_can_create_shift_evaluation := true; v_can_edit_shift_evaluation := true; v_can_approve_shift_evaluation := true;
  elsif v_role_key = 'customer_service_manager' then
    v_can_view_shift_performance := true;
  elsif v_role_key in ('shift_supervisor_morning','shift_supervisor_evening') then
    v_can_view_shift_performance := true; v_can_create_shift_evaluation := true; v_can_edit_shift_evaluation := true;
  end if;
  v_effective := jsonb_set(v_effective, '{view_shift_performance}', to_jsonb(v_can_view_shift_performance and coalesce(nullif(v_account_permissions->>'view_shift_performance','')::boolean, true) and coalesce(nullif(v_override_json->>'view_shift_performance','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{create_shift_evaluation}', to_jsonb(v_can_create_shift_evaluation and coalesce(nullif(v_account_permissions->>'create_shift_evaluation','')::boolean, true) and coalesce(nullif(v_override_json->>'create_shift_evaluation','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{edit_shift_evaluation}', to_jsonb(v_can_edit_shift_evaluation and coalesce(nullif(v_account_permissions->>'edit_shift_evaluation','')::boolean, true) and coalesce(nullif(v_override_json->>'edit_shift_evaluation','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{approve_shift_evaluation}', to_jsonb(v_can_approve_shift_evaluation and coalesce(nullif(v_account_permissions->>'approve_shift_evaluation','')::boolean, true) and coalesce(nullif(v_override_json->>'approve_shift_evaluation','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{delete_shift_evaluation}', to_jsonb(v_can_delete_shift_evaluation and coalesce(nullif(v_account_permissions->>'delete_shift_evaluation','')::boolean, true) and coalesce(nullif(v_override_json->>'delete_shift_evaluation','')::boolean, true)), true);

  if v_role_key in ('general_manager','executive_manager','branches_manager','admin','branch_manager') then
    v_can_view_points := true; v_can_manage_points := true; v_can_approve_points := true; v_can_create_reward := true; v_can_create_deduction := true; v_can_edit_points_transaction := true; v_can_export_points_report := true;
  elsif v_role_key in ('shift_supervisor_morning','shift_supervisor_evening') then
    v_can_view_points := true; v_can_create_reward := true; v_can_create_deduction := true;
  elsif v_role_key in ('customer_service_manager','customer_service','pharmacist','team_dawaa_alpha') then v_can_view_points := true;
  end if;
  v_effective := jsonb_set(v_effective, '{view_points}', to_jsonb(v_can_view_points and coalesce(nullif(v_account_permissions->>'view_points','')::boolean, true) and coalesce(nullif(v_override_json->>'view_points','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{manage_points}', to_jsonb(v_can_manage_points and coalesce(nullif(v_account_permissions->>'manage_points','')::boolean, true) and coalesce(nullif(v_override_json->>'manage_points','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{approve_points}', to_jsonb(v_can_approve_points and coalesce(nullif(v_account_permissions->>'approve_points','')::boolean, true) and coalesce(nullif(v_override_json->>'approve_points','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{create_reward}', to_jsonb(v_can_create_reward and coalesce(nullif(v_account_permissions->>'create_reward','')::boolean, true) and coalesce(nullif(v_override_json->>'create_reward','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{create_deduction}', to_jsonb(v_can_create_deduction and coalesce(nullif(v_account_permissions->>'create_deduction','')::boolean, true) and coalesce(nullif(v_override_json->>'create_deduction','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{edit_points_transaction}', to_jsonb(v_can_edit_points_transaction and coalesce(nullif(v_account_permissions->>'edit_points_transaction','')::boolean, true) and coalesce(nullif(v_override_json->>'edit_points_transaction','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{export_points_report}', to_jsonb(v_can_export_points_report and coalesce(nullif(v_account_permissions->>'export_points_report','')::boolean, true) and coalesce(nullif(v_override_json->>'export_points_report','')::boolean, true)), true);

  if v_role_key in ('general_manager','executive_manager','branches_manager','admin','manager') then
    v_can_view_salary_calculator := true; v_can_manage_payroll := true;
  elsif v_role_key = 'customer_service_manager' then v_can_view_salary_calculator := true;
  end if;
  v_effective := jsonb_set(v_effective, '{view_salary_calculator}', to_jsonb(v_can_view_salary_calculator and coalesce(nullif(v_account_permissions->>'view_salary_calculator','')::boolean, true) and coalesce(nullif(v_override_json->>'view_salary_calculator','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{manage_payroll}', to_jsonb(v_can_manage_payroll and coalesce(nullif(v_account_permissions->>'manage_payroll','')::boolean, true) and coalesce(nullif(v_override_json->>'manage_payroll','')::boolean, true)), true);
  v_effective := v_effective - 'manage_salary_calculator';

  if v_role_key in ('general_manager','executive_manager','branches_manager','admin','manager') then
    v_can_view_incentives := true;
    v_can_manage_incentives := true;
    v_can_view_quarterly_incentives := true;
    v_can_manage_quarterly_incentives := true;
    v_can_view_penalty_management := true;
    v_can_manage_penalty_management := true;
  elsif v_role_key = 'branch_manager' then
    v_can_view_incentives := true;
    v_can_view_quarterly_incentives := true;
    v_can_view_penalty_management := true;
  end if;
  v_effective := jsonb_set(v_effective, '{view_incentives}', to_jsonb(v_can_view_incentives and coalesce(nullif(v_account_permissions->>'view_incentives','')::boolean, true) and coalesce(nullif(v_override_json->>'view_incentives','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{manage_incentives}', to_jsonb(v_can_manage_incentives and coalesce(nullif(v_account_permissions->>'manage_incentives','')::boolean, true) and coalesce(nullif(v_override_json->>'manage_incentives','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{view_quarterly_incentives}', to_jsonb(v_can_view_quarterly_incentives and coalesce(nullif(v_account_permissions->>'view_quarterly_incentives','')::boolean, true) and coalesce(nullif(v_override_json->>'view_quarterly_incentives','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{manage_quarterly_incentives}', to_jsonb(v_can_manage_quarterly_incentives and coalesce(nullif(v_account_permissions->>'manage_quarterly_incentives','')::boolean, true) and coalesce(nullif(v_override_json->>'manage_quarterly_incentives','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{view_penalty_management}', to_jsonb(v_can_view_penalty_management and coalesce(nullif(v_account_permissions->>'view_penalty_management','')::boolean, true) and coalesce(nullif(v_override_json->>'view_penalty_management','')::boolean, true)), true);
  v_effective := jsonb_set(v_effective, '{manage_penalty_management}', to_jsonb(v_can_manage_penalty_management and coalesce(nullif(v_account_permissions->>'manage_penalty_management','')::boolean, true) and coalesce(nullif(v_override_json->>'manage_penalty_management','')::boolean, true)), true);

  return v_effective;
end;
$function$

CREATE OR REPLACE FUNCTION public.dawaa_customer_request_permission_allowed(p_actor_id uuid, p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_role text;
  v_account_permissions jsonb := '{}'::jsonb;
  v_override jsonb := '{}'::jsonb;
  v_role_allowed boolean := false;
begin
  if p_actor_id is null or p_permission not in ('view_customer_requests','manage_customer_requests') then
    return false;
  end if;

  select lower(trim(coalesce(sa.role,''))), coalesce(sa.permissions,'{}'::jsonb)
    into v_role, v_account_permissions
  from public.staff_accounts sa
  where sa.id = p_actor_id
    and coalesce(sa.active,false)
    and coalesce(sa.can_login,false)
  limit 1;
  if not found then return false; end if;

  if p_permission = 'view_customer_requests' then
    v_role_allowed := v_role in (
      'general_manager','executive_manager','branches_manager','admin',
      'branch_manager','customer_service_manager',
      'shift_supervisor_morning','shift_supervisor_evening',
      'pharmacist','customer_service'
    );
  else
    v_role_allowed := v_role in (
      'general_manager','executive_manager','branches_manager','admin',
      'branch_manager','customer_service_manager',
      'shift_supervisor_morning','shift_supervisor_evening',
      'pharmacist'
    );
  end if;

  select coalesce(jsonb_object_agg(spo.permission_key, spo.allowed), '{}'::jsonb)
    into v_override
  from public.staff_permission_overrides spo
  where spo.staff_account_id = p_actor_id
    and spo.permission_key = p_permission;

  return v_role_allowed
    and coalesce(nullif(v_account_permissions->>p_permission,'')::boolean, true)
    and coalesce(nullif(v_override->>p_permission,'')::boolean, true);
end;
$function$

CREATE OR REPLACE FUNCTION public.dawaa_create_or_link_customer_followup_v1(p_customer_id text DEFAULT NULL::text, p_customer_code text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_customer_phone text DEFAULT NULL::text, p_branch text DEFAULT NULL::text, p_request_type text DEFAULT 'general'::text, p_request_details text DEFAULT NULL::text, p_followup_reason text DEFAULT NULL::text, p_priority text DEFAULT 'متوسطة'::text, p_next_followup_date date DEFAULT NULL::date, p_client_request_id text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
declare a public.staff_accounts; v_role text; v_branch text:=trim(coalesce(p_branch,''));
begin
  a:=public.dawaa_require_customer_service_actor_v1(false);
  v_role:=lower(trim(coalesce(a.role,a.staff_role,'')));
  if nullif(trim(coalesce(p_customer_name,'')),'') is null then raise exception 'اسم العميل مطلوب'; end if;
  if v_branch not in ('فرع الشامي','فرع شكري') then raise exception 'فرع العميل غير صحيح'; end if;
  if v_role not in ('general_manager','executive_manager','branches_manager','branch_manager','customer_service_manager')
     and nullif(trim(coalesce(a.branch,'')),'') is distinct from v_branch then raise exception 'لا يمكن إنشاء متابعة خارج فرع الحساب'; end if;
  return public.find_or_create_open_customer_followup(p_customer_id,p_customer_code,trim(p_customer_name),p_customer_phone,v_branch,
    coalesce(nullif(trim(coalesce(p_request_type,'')),''),'general'),p_request_details,p_followup_reason,p_priority,p_next_followup_date,
    a.id::text,coalesce(a.name,a.username),coalesce(nullif(trim(coalesce(p_client_request_id,'')),''),'followup:'||gen_random_uuid()::text),
    coalesce(nullif(trim(coalesce(p_source,'')),''),'manual'));
end $function$

CREATE OR REPLACE FUNCTION public.dawaa_customer_service_branch_scope_v1()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
declare
  a public.staff_accounts;
  v_id uuid;
  v_role text;
  v_branch text;
begin
  v_id := public.dawaa_current_staff_account_id_strict();
  if v_id is null then return null; end if;

  select * into a
  from public.staff_accounts
  where id = v_id
    and coalesce(active,false)
    and coalesce(can_login,false);
  if not found then return null; end if;

  v_role := lower(trim(coalesce(a.role,a.staff_role,'')));
  v_branch := nullif(trim(coalesce(a.branch,'')), '');

  if v_role in ('admin','owner','general_manager','executive_manager','branches_manager','manager','team_dawaa_alpha') then
    return '*';
  end if;

  return v_branch;
end
$function$

CREATE OR REPLACE FUNCTION public.dawaa_require_customer_service_actor_v1(p_manager_only boolean DEFAULT false)
 RETURNS staff_accounts
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
declare
  v_id uuid;
  v_actor public.staff_accounts;
  v_role text;
  v_perms jsonb;
  v_can_manage boolean;
begin
  v_id := public.dawaa_current_staff_account_id_strict();
  if v_id is null then raise exception 'يجب تسجيل الدخول بحساب موظف نشط'; end if;

  select * into v_actor from public.staff_accounts
  where id = v_id and coalesce(active,false) and coalesce(can_login,false);
  if not found then raise exception 'حساب الموظف غير نشط أو غير مصرح له'; end if;

  v_role := lower(trim(coalesce(v_actor.role,'')));
  v_perms := public.get_user_permissions(v_id);
  v_can_manage := v_role in ('general_manager','executive_manager','branches_manager','branch_manager','customer_service_manager')
    or public.dawaa_jsonb_has_true_any(v_perms, array['assign_followup','manage_customer_requests']);

  if p_manager_only and not v_can_manage then
    raise exception 'الأرشفة والاستعادة متاحة للمدير أو مسؤول خدمة العملاء المخول فقط';
  end if;
  return v_actor;
end;
$function$

CREATE OR REPLACE FUNCTION public.find_or_create_open_customer_followup(p_customer_id text, p_customer_code text, p_customer_name text, p_customer_phone text, p_branch text, p_request_type text, p_request_details text, p_followup_reason text, p_priority text, p_next_followup_date date, p_actor_staff_id text, p_actor_name text, p_client_request_id text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_staff record;
  v_identity text;
  v_case_type text := coalesce(nullif(btrim(p_request_type), ''), 'general');
  v_branch text := nullif(btrim(p_branch), '');
  v_existing public.daily_followups%rowtype;
  v_created public.daily_followups%rowtype;
  v_lock_key text;
  v_today text := to_char(timezone('Africa/Cairo', now()), 'YYYY-MM-DD');
begin
  if nullif(btrim(p_actor_staff_id), '') is null then
    raise exception 'actor_staff_id_required';
  end if;

  select * into v_staff
  from public.resolve_staff_account_safe(p_actor_staff_id)
  limit 1;

  if v_staff.id is null or v_staff.active is not true or v_staff.can_login is not true then
    raise exception 'active_staff_account_required';
  end if;

  if coalesce(v_staff.role, '') not in (
    'customer_service','customer_service_manager','general_manager','branch_manager',
    'branches_manager','admin','doctor','pharmacist','shift_supervisor','shift_supervisor_evening'
  ) then
    raise exception 'followup_create_permission_denied';
  end if;

  v_identity := public.dawaa_customer_identity_key_v1(
    p_customer_id, p_customer_code, p_customer_phone, p_customer_name
  );
  if v_identity is null then
    raise exception 'customer_identity_required';
  end if;
  if v_branch is null then
    raise exception 'branch_required';
  end if;

  if nullif(btrim(p_client_request_id), '') is not null then
    select * into v_existing
    from public.daily_followups
    where client_request_id = btrim(p_client_request_id)
    limit 1;
    if v_existing.id is not null then
      return jsonb_build_object('followup_id', v_existing.id, 'created', false, 'idempotent_replay', true, 'identity_key', v_existing.identity_key);
    end if;
  end if;

  v_lock_key := v_identity || '|' || v_branch || '|' || v_case_type;
  perform pg_advisory_xact_lock(hashtextextended(v_lock_key, 0));

  select * into v_existing
  from public.daily_followups
  where identity_key = v_identity
    and branch = v_branch
    and coalesce(nullif(btrim(request_type), ''), 'general') = v_case_type
    and completed_at is null
    and cancelled_at is null
    and archived_at is null
    and is_hidden is false
    and duplicate_of is null
  order by created_at desc nulls last
  limit 1
  for update;

  if v_existing.id is not null then
    update public.daily_followups
      set updated_at = now(),
          next_followup_date = coalesce(p_next_followup_date, next_followup_date),
          priority = coalesce(nullif(btrim(p_priority), ''), priority)
    where id = v_existing.id;

    insert into public.customer_service_followup_events(
      followup_id, event_type, event_status, actor_staff_id, actor_name, notes, metadata
    ) values (
      v_existing.id,
      'request_linked',
      'open',
      p_actor_staff_id,
      coalesce(nullif(btrim(p_actor_name), ''), v_staff.name),
      coalesce(nullif(btrim(p_request_details), ''), nullif(btrim(p_followup_reason), ''), 'طلب متابعة إضافي'),
      jsonb_build_object(
        'source', coalesce(nullif(btrim(p_source), ''), 'manual'),
        'request_type', v_case_type,
        'client_request_id', nullif(btrim(p_client_request_id), ''),
        'requested_at', now()
      )
    );

    return jsonb_build_object('followup_id', v_existing.id, 'created', false, 'linked_to_open_case', true, 'identity_key', v_identity);
  end if;

  insert into public.daily_followups(
    date, customer_id, customer_name, name, phone, customer_phone, customer_code,
    branch, status, followup_status, contact_status, followup_type, request_type,
    request_details, followup_reason, priority, next_followup_date, created_by,
    created_by_name, requested_by_staff_id, request_source, identity_key,
    client_request_id, is_hidden, is_duplicate
  ) values (
    v_today, nullif(btrim(p_customer_id), ''), nullif(btrim(p_customer_name), ''),
    nullif(btrim(p_customer_name), ''), public.dawaa_normalize_egyptian_mobile_v1(p_customer_phone),
    public.dawaa_normalize_egyptian_mobile_v1(p_customer_phone), nullif(btrim(p_customer_code), ''),
    v_branch, 'not_started', 'pending', 'pending', v_case_type, v_case_type,
    nullif(btrim(p_request_details), ''), nullif(btrim(p_followup_reason), ''),
    coalesce(nullif(btrim(p_priority), ''), 'متوسطة'), p_next_followup_date,
    p_actor_staff_id, coalesce(nullif(btrim(p_actor_name), ''), v_staff.name),
    p_actor_staff_id, coalesce(nullif(btrim(p_source), ''), 'manual'), v_identity,
    nullif(btrim(p_client_request_id), ''), false, false
  ) returning * into v_created;

  insert into public.customer_service_followup_events(
    followup_id, event_type, event_status, actor_staff_id, actor_name, notes, metadata
  ) values (
    v_created.id, 'created', 'open', p_actor_staff_id,
    coalesce(nullif(btrim(p_actor_name), ''), v_staff.name),
    coalesce(nullif(btrim(p_request_details), ''), nullif(btrim(p_followup_reason), ''), 'إنشاء متابعة'),
    jsonb_build_object('source', coalesce(nullif(btrim(p_source), ''), 'manual'), 'request_type', v_case_type, 'client_request_id', nullif(btrim(p_client_request_id), ''))
  );

  return jsonb_build_object('followup_id', v_created.id, 'created', true, 'linked_to_open_case', false, 'identity_key', v_identity);
exception
  when unique_violation then
    if nullif(btrim(p_client_request_id), '') is not null then
      select * into v_existing from public.daily_followups where client_request_id = btrim(p_client_request_id) limit 1;
      if v_existing.id is not null then
        return jsonb_build_object('followup_id', v_existing.id, 'created', false, 'idempotent_replay', true, 'identity_key', v_existing.identity_key);
      end if;
    end if;
    raise;
end;
$function$
